style.css:
@-moz-document domain("roblox.com") {
body {
    background: url("https://i.pinimg.com/736x/85/17/b4/8517b4d30e4175f8322f51272175f3d0.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
    color: white !important;
  }

  .rbx-navbar, .rbx-header, .rbx-footer {
    background-color: rgba(0, 0, 0, 0.6) !important;
    backdrop-filter: blur(10px);
  }

  .container, .content, .section, .rbx-page, .rbx-body {
    background-color: rgba(0, 0, 0, 0.4) !important;
    backdrop-filter: blur(5px);
    border-radius: 12px;
    padding: 10px;
  }

  a, .btn-primary {
    color: #ffccff !important;
    background-color: rgba(255, 255, 255, 0.1) !important;
    border: 1px solid #ffccff !important;
  }

  input, textarea, select {
    background-color: rgba(255, 255, 255, 0.2) !important;
    color: white !important;
    border: 1px solid white !important;
  }
}
